// CParser.h// Copyright © 1999-2000 by Apple Computer, Inc. All rights reserved. /*	Change History:		10/13/00	CWP6 support: namespacing. 		04/20/00	Move CTerm and CToken back here. 		04/18/00	Remove CTypeCatcherTerm and CTypeCatcherToken. The type catcher							was not being used and it was the only token that changed its 							identifier. 							Remove parse namespace. 		04/17/00	Rename nodes to terms. Remove string versions of Parse. 							Move CTerm and CToken to their own units. 		12/02/99	Remove all the subterms and make a set without any 							duplicates before deleting. 							Un-inline the destructors so it will be easier to debug them. 		11/30/99	Fixed FirstSubToken so it doesn't crash if there							are no sub-tokens. 		11/29/99	Dump tokens. 		10/29/99	Added FindNextSiblingToken.		10/26/99	Rework to handle cycles.  Eliminated Saturated() since it							was not being used anywhere.  Changed fActSubMatch to a							local variable of the Parse function.  De-virtualized							Satisfied and Fulfilled.  Added FindSiblingToken.		10/21/99	Provide an accessor so subclasses can get const access							to the parse stream. This is needed so they can get							back to the protocol for handling unsolicited responses. 		10/20/99	Added CParseNub which is a generic parse term that							can create a generic token in the resulting tree.		10/18/99	Added FirstSubToken and NthSubToken.		10/13/99	Add CTextPtr-style parsing.		10/08/99	ParseTerm can now be set to scan subterms in an ordered							manner.  Added optional match counts to AddSubTerm.		10/05/99	Start all enums with 'e' rather than 'sc'.		10/01/99	Added GetSiblingToken.		09/27/99	Yet another major modification in approach.  The broadcast							mechanism has been replaced with a chain-of-responsibility.							Also incorporated a token tree which mimics the same							class design as the parse terms.		09/16/99	Added scUnexpectedLineID.		09/08/99	Created.*/#ifndef __CParser__#define __CParser__#pragma once// Network// ACS#ifndef __CException_AC__#include "CException_AC.h"#endif#ifndef __CTextPtr__#include "CTextPtr.h"#endif#ifndef __Types_AC__#include "Types_AC.h"#endif// ANSI#include <algorithm>#include <cctype>#include <set>#include <sstream>#include <string>#include <vector>using namespace std;// External//========================================================================================// Globals//========================================================================================//----------------------------------------------------------------------------------------// Parsing Flags//----------------------------------------------------------------------------------------enum WhiteSpace{	eSkipWhiteSpace			= true,	eDontSkipWhiteSpace		= false};enum ParseOrdering{	eOrdered				= true,	eNotOrdered				= false};//========================================================================================//----------------------------------------------------------------------------------------// Forwards//----------------------------------------------------------------------------------------class CToken;class CTerm;//----------------------------------------------------------------------------------------//========================================================================================// Base Parsing Classes//========================================================================================typedef vector<CTerm*>		CTermList;typedef set<CTerm*>		CTermSet;//========================================================================================// CTerm//========================================================================================class CTerm// CTerm is the base class for terms in a parsing structure.  Every parse // term can have zero or more subterms with certain exceptions.  NOTE: Once a subterm// has been added via AddSubTerm it belongs to this term and will be destroyed// by our destructor.  This means that all subterms of a CTerm// should be allocated via new.//// A note on validating a grammar term: In order to support cyclic graphs it// was necessary to save and restore state information (fActualMatch) that// could and would be modified unintentionally if a grammar term found// itself a sub-term of itself.  This state information is saved in the// Parse functions in which it is modified and restored upon return from // any subordinate calls to Parse.{public:	CTerm(	unsigned short	minimumMatch,			unsigned short	maximumMatch,			IDType			identifier = kNoIdentifier_AC,			unsigned short	minSubMatch = 0,			unsigned short	maxSubMatch = 32767,			IDType			notifyID = kNoIdentifier_AC,			ParseOrdering	ordered = eNotOrdered,			WhiteSpace		skipWhiteSpace = eSkipWhiteSpace);	CTerm(	IDType			identifier,			IDType			notifyID = kNoIdentifier_AC,			ParseOrdering	ordered = eNotOrdered,			WhiteSpace		skipWhiteSpace = eSkipWhiteSpace);	CTerm();	virtual ~CTerm();	// Parsing	virtual bool	Parse(	CTextPtr&			textPtr,							CToken*				parentToken);		// Parse the string pointed to by textPtr.  Do not update offset		// until you are sure that the parse was successful.		void	SetOrdered(ParseOrdering newOrdered = eNotOrdered) { fOrdered = newOrdered; }		// Indicates if this term should scan its subterms in an ordered manner.	// Term Status	bool	Satisfied() const { return fActualMatch >= fMinimumMatch; }		// Returns whether this term has been partially satisfied.		bool	Fulfilled() const { return fActualMatch == fMaximumMatch; }		// Returns whether this term has been fully satisfied.		void	Reset()  { fActualMatch = 0; }		// Clears this term's actual match count.		bool	SkipWhiteSpace(CTextPtr& textPtr) const;		// Skip over whitespace in the input string.		// •••  I decided to go ahead and incorporate terms that know something		// about text and the possible need to skip whitespace into the base		// class.		void	SetMinimumMatch(unsigned short minimumMatch) { fMinimumMatch = minimumMatch; }		// Set our minimum match requirement.			void	SetMaximumMatch(unsigned short maximumMatch) { fMaximumMatch = maximumMatch; }		// Set our maximum match requirement.			// Notification	//	// Notification is done using a chain-of-responsibility approach up through	// the token tree created during the parse.		IDType	GetIdentifier() const { return fIdentifier; }		// Retrieve the identifier of this term.	IDType	GetNotifyID() const { return fNotifyID; }		// Retrieve the notify ID this term will emit.	// Subterm management.	void	AddSubTerm(	CTerm* 	aSubTerm, 						unsigned short	minimumMatch = 0, 						unsigned short	maximumMatch = 0);		// Add a subterm.	//	void	SetParent(CTerm* parent) { fParent = parent; }//		// Set our parent for chain-of-responsibility.//		//	CTerm*		GetParent() const { return fParent; }//		// Set our parent for chain-of-responsibility.			void	ResetSubTerms();		// Reset our sub-terms. 	void	ReleaseSubTerms(CTermSet& terms);		// Removes our sub-terms from our list and adds them to the set. 		// Recurses. protected:	unsigned short		fMinimumMatch;	// Minimum times this must be matched.	unsigned short		fMaximumMatch;	// Maximum times than can be matched.	unsigned short		fActualMatch;	// Actual time this has been matched.	IDType				fIdentifier;	// A unique identifier.	IDType				fNotifyID;		// The notify ID for this particular term.	// Subterm management.	CTermList			fSubTerms;		// A list of our subterms.	unsigned short		fMinSubMatch;	// Minimum subs which must match.	unsigned short		fMaxSubMatch;	// Maximum subs which can match.//	CTerm*				fParent;		// Our parent grammar term.	ParseOrdering		fOrdered;		// If true then parsing of subterms must										// succeed from let-to-right.  Otherwise,										// scan until a subterm is found which is										// satisfied by the current term.	WhiteSpace			fSkipWhiteSpace;	// If true then skip white space before parsing.	// Debugging support.#if qDebug	unsigned short			fDebugID;	// A unique debug identified.	static unsigned short	sfDebugID;	// The static holder of the next debug id.#endif};//========================================================================================// Base Token Classes//========================================================================================typedef vector<CToken*>		CTokenList;typedef CTokenList::iterator		CTokenListIterator;typedef CTokenList::const_iterator	CConstTokenListIterator;//========================================================================================// CToken//========================================================================================class CToken// CToken is the base class for tokens created in the parsing process.{public:	CToken(CToken* parent = NULL, CTerm* term = NULL);	virtual ~CToken();	// Notification	//	// Notification is done using a chain-of-responsibility approach up through	// the token tree created during the parse.		IDType		GetNotifyID() const;		// Retrieve the notify ID this term will emit.		IDType		GetIdentifier() const;		// Retrieve the identifier for this token.	void		DoNotification();		// Notify parent of successful completion.		virtual void HandleNotification(CToken* notifier);		// Decide what to do when a certain notification is received.	// Sub-token management.	void		AddSubToken(CToken* aToken);		void		RemoveSubToken(CToken* tokenToRemove);		// Remove the given token but do not delete it.		CToken*		FirstSubToken() const;		// Return the first subtoken.	CToken*		NthSubToken(unsigned short n) const;		// Return the nth subtoken.			CToken*		FindSubToken(const IDType tokenID, bool recurse = true) const;		// Locate the subtoken with the given identifier.			CToken*		FindParentToken(const IDType tokenID) const;		// Locate the parent token with the given identifier.			CToken*		GetParentToken() const { return fParent; }		// Return our parent token.		void		SetParent(CToken* parent) { fParent = parent; }		// Set our parent for chain-of-responsibility.			bool		ThrowAway() const { return fThrowAway; }		// Return true if this token should not be processed any further.		#if qDebug	virtual void	Dump(ostream& toStream, short level = 0) const;	virtual void	DumpContents(ostream& toStream, short level) const;#endifprotected:	CToken*				fParent;		// The token which contains this one.	CTerm*				fParseTerm;		// The parse term which created this token.	CTokenList			fTokens;		// A list of our sub-tokens.//	IDType				fIdentifier;	// A unique identifier.//	IDType				fNotifyID;		// The notify ID for this particular token.	bool				fThrowAway;		// Set to true to terminate processing of this token.};//========================================================================================// Globals//========================================================================================//----------------------------------------------------------------------------------------// Term IDs//----------------------------------------------------------------------------------------enum{	// Notification IDs for ubiquitious parsing components.		eIntegerID			= 'INTG',	eDoneID				= 'DONE',	// Notification ID for TypeCatcher parsing term.	eTypeCatcherID		= 'TYPE'};//========================================================================================//----------------------------------------------------------------------------------------bool InsensitiveCompare(const char c1, const char c2);//========================================================================================// CParseNub//========================================================================================class CParseNub : public CTerm// CParseNub is a generic parse term which consumes none of the string and// always succeeds.  It also creates a generic CToken.{public:	CParseNub(	unsigned short	minimumMatch = 1,				unsigned short	maximumMatch = 1,				IDType			identifier = kNoIdentifier_AC,				unsigned short	minSubMatch = 0,				unsigned short	maxSubMatch = 32767,				IDType			notifyID = kNoIdentifier_AC,				ParseOrdering	ordered = eNotOrdered,				WhiteSpace		skipWhiteSpace = eSkipWhiteSpace)		:	CTerm(minimumMatch, maximumMatch, identifier, minSubMatch, maxSubMatch, notifyID, ordered, skipWhiteSpace)		{ }		~CParseNub();	virtual bool	Parse(	CTextPtr&			textPtr,							CToken*				parentToken);		// Simply create a token and continue the parse.};//========================================================================================// CParseStream//========================================================================================class CParseStream : public CTerm// CParseStream is a simple parse term which understands how to parse a// stringstream by breaking it down into lines and parsing each separately.{public:	CParseStream(CTextPtr* textPtr)		:	CTerm(1, 1, kNoIdentifier_AC, 1, 1),			//fParseStream(NULL),			fParsePtr(textPtr),			fParseSucceeded(false),			fParseDone(false)			//fUseTextPtr(true)		{ }	~CParseStream();//	bool			GetNextLine();	virtual bool	ParseStream(CToken* baseToken);		virtual void	Reset() { fOffset = 0; fParseSucceeded = false; }		// Reset the ParseStream.  Usefull if you're restarting.		void			SetDone() { fParseDone = true; }//	stringstream&	GetParseStream() { return *fParseStream; }		static const unsigned short scMaxStringLength = 1024;protected://	stringstream*		fParseStream;		// The stream being parsed.	CTextPtr*			fParsePtr;			// A pointer into a CTextBuffer.	string			fResponseString;	// The current line being parsed.	string			fPreString;			// A prefetched line.	string::size_type	fOffset;			// Current position in string.	bool				fParseSucceeded;	// True upon completion of a successful parse.	bool				fParseDone;			// True when parsing is done.//	bool				fUseTextPtr;		// True for CTextPtr, stringstream otherwise.};//========================================================================================// CParseStreamToken//========================================================================================class CParseStreamToken : public CToken// CParseStreamToken is a token which contains a specific literal.{public:	CParseStreamToken(CParseStream* theParseStream)		:	CToken(),			fParseStream(theParseStream)		{ }	~CParseStreamToken();		void		HandleNotification(CToken* notifier);		// Handle a 'DONE' notification.	const CParseStream* GetParseStream() const	{ return fParseStream; }	CParseStream* GetParseStream()	{ return fParseStream; }private:	CParseStream*		fParseStream;};//========================================================================================// CLiteralTerm//========================================================================================class CLiteralTerm : public CTerm{// CLiteralTerm is a parse term which tests for a specific literal.public:	CLiteralTerm(	const string	theLiteral,					unsigned short	minimumMatch = 1,					unsigned short	maximumMatch = 1,					IDType			identifier = kNoIdentifier_AC,					unsigned short	minSubMatch = 0,					unsigned short	maxSubMatch = 32767,					IDType			notifyID = kNoIdentifier_AC,					ParseOrdering	ordered = eNotOrdered,					WhiteSpace		skipWhiteSpace = eSkipWhiteSpace)		:	CTerm(minimumMatch, maximumMatch, identifier, minSubMatch, maxSubMatch, notifyID, ordered, skipWhiteSpace),			fLiteral(theLiteral)		{ }	~CLiteralTerm();	const string& GetLiteral() const { return fLiteral; }		virtual bool	Parse(	CTextPtr&			textPtr,							CToken*				parentToken);		// Look for an exact match of the given literal string.private:	const string	fLiteral;};//========================================================================================// CLiteralToken//========================================================================================class CLiteralToken : public CToken// CLiteralToken is a token which contains a specific literal.{public:	CLiteralToken(	CToken*			parent,			 		CLiteralTerm*	term)		:	CToken(parent, term),			fLiteral(term->GetLiteral())		{ }		~CLiteralToken();	const string&	GetLiteral() const { return fLiteral; }	#if qDebug && qMacApp	virtual void	DumpContents(ostream& toStream, short level) const;#endifprivate:	string		fLiteral;};//========================================================================================// CIntegerTerm//========================================================================================class CIntegerTerm : public CTerm// CIntegerTerm is a parse term which scans the input string for one or more numeric// digits.  If it finds at least one integer then it plugs the value into the// parent term's value list.  OR WHATEVER!?!{public:	CIntegerTerm(	unsigned short	minimumMatch = 1,					unsigned short	maximumMatch = 1,					IDType			identifier = kNoIdentifier_AC,					unsigned short	minSubMatch = 0,					unsigned short	maxSubMatch = 32767,					IDType			notifyID = kNoIdentifier_AC,					ParseOrdering	ordered = eNotOrdered,					WhiteSpace		skipWhiteSpace = eSkipWhiteSpace)		:	CTerm(minimumMatch, maximumMatch, identifier, minSubMatch, maxSubMatch, notifyID, ordered, skipWhiteSpace)		{ }		~CIntegerTerm();	virtual bool	Parse(	CTextPtr&			textPtr,							CToken*				parentToken);		// Look for a number consisting of digits.  It must have at least		// one digit.};//========================================================================================// CIntegerToken//========================================================================================class CIntegerToken : public CToken// CIntegerToken is a token representing an integer detected during parsing.{public:	CIntegerToken(	CToken*			parent,					CIntegerTerm*	term,					UInt32			theInteger)		:	CToken(parent, term),			fInteger(theInteger)		{ }		~CIntegerToken();	UInt32		GetInteger() const { return fInteger; }	#if qDebug && qMacApp	virtual void	DumpContents(ostream& toStream, short level) const;#endifprivate:	UInt32		fInteger;};//========================================================================================// CKeywordTerm//========================================================================================class CKeywordTerm : public CTerm// CKeywordTerm is a parse term which scans the input string for one or more // characters until one of the delimeters is found.{public:	CKeywordTerm(	const string	delimeters,					unsigned short	minimumMatch = 1,					unsigned short	maximumMatch = 1,					IDType			identifier = kNoIdentifier_AC,					unsigned short	minSubMatch = 0,					unsigned short	maxSubMatch = 32767,					IDType			notifyID = kNoIdentifier_AC,					ParseOrdering	ordered = eNotOrdered,					WhiteSpace		skipWhiteSpace = eSkipWhiteSpace)		:	CTerm(minimumMatch, maximumMatch, identifier, minSubMatch, maxSubMatch, notifyID, ordered, skipWhiteSpace),			fDelimeters(delimeters)		{ }		~CKeywordTerm();	virtual bool	Parse(	CTextPtr&			textPtr,							CToken*				parentToken);		// Parse the string until finding a delimeter.protected:	const string	fDelimeters;};//========================================================================================// CKeywordToken//========================================================================================class CKeywordToken : public CToken// CKeywordToken is a parse term which scans the input string for one or more // characters until one of the delimeters is found.{public:	CKeywordToken(	CToken*			parent,					CKeywordTerm*	term,					const string&	keyword)		:	CToken(parent, term),			fKeyword(keyword)		{ }		~CKeywordToken();	const string&	GetKeyword() const { return fKeyword; }	#if qDebug && qMacApp	virtual void	DumpContents(ostream& toStream, short level) const;#endifprotected:	string			fKeyword;};//========================================================================================// CRestOfLineTerm//========================================================================================class CRestOfLineTerm : public CTerm// CRestOfLineTerm is a parse term which grabs the rest of the string without// any specific rules.{public:	CRestOfLineTerm(IDType			identifier = kNoIdentifier_AC,					IDType			notifyID = kNoIdentifier_AC,					WhiteSpace		skipWhiteSpace = eSkipWhiteSpace)		:	CTerm(0, 1, identifier, 0, 0, notifyID, eNotOrdered, skipWhiteSpace)		{ }		~CRestOfLineTerm();	virtual bool	Parse(	CTextPtr&			textPtr,							CToken*				parentToken);		// Simply scan the rest of the string.};//========================================================================================// CRestOfLineToken//========================================================================================class CRestOfLineToken : public CToken// CRestOfLine is a parse term which grabs the rest of the string without// any specific rules.{public:	CRestOfLineToken(	CToken*				parent,						CRestOfLineTerm*	term,						const string&		restOfLine)		:	CToken(parent, term),			fString(restOfLine)		{ }		~CRestOfLineToken();	const string&	GetString() const { return fString; }	#if qDebug && qMacApp	virtual void	DumpContents(ostream& toStream, short level) const;#endifprotected:	string		fString;		// The rest of the line.};#endif // __CParser__